package com.readerlb.app.importer

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertNotNull
import org.junit.Assert.assertNull
import org.junit.Assert.assertTrue
import org.junit.Assert.fail
import org.junit.Test
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.nio.file.Files
import java.util.zip.ZipEntry
import java.util.zip.ZipOutputStream

class ReaderLbTransferManagerTest {

    @Test
    fun detectsPortableReaderLbPackage() {
        val bytes = packageBytes()

        val info =
            inspectReaderLbTransfer(
                ByteArrayInputStream(
                    bytes
                )
            )

        assertNotNull(info)
        assertEquals(
            "Тестовый тайтл",
            info?.title
        )
        assertEquals(
            41,
            info?.chapterCount
        )
        assertEquals(
            "0",
            info?.firstChapter
        )
        assertEquals(
            "89",
            info?.lastChapter
        )
    }

    @Test
    fun ordinaryZipIsNotDetectedAsTransfer() {
        val bytes =
            ByteArrayOutputStream()
                .also { output ->
                    ZipOutputStream(
                        output
                    ).use { zip ->
                        zip.putNextEntry(
                            ZipEntry(
                                "random.txt"
                            )
                        )
                        zip.write(
                            "hello"
                                .toByteArray()
                        )
                        zip.closeEntry()
                    }
                }
                .toByteArray()

        assertNull(
            inspectReaderLbTransfer(
                ByteArrayInputStream(
                    bytes
                )
            )
        )
    }

    @Test
    fun manifestCanAppearAfterBookFiles() {
        val bytes =
            zipBytes(
                "book/900000001--test/info.json" to
                    "{}",
                "book/900000001--test/chapters.json" to
                    "[]",
                "readerlb-transfer.json" to
                    manifestText()
            )

        val info =
            inspectReaderLbTransfer(
                ByteArrayInputStream(
                    bytes
                )
            )

        assertNotNull(info)
        assertEquals(
            "900000001--test",
            info?.slugUrl
        )
    }

    @Test
    fun ordinaryZipWithUnsafePathStillFallsBackToNormalZipHandling() {
        val bytes =
            zipBytes(
                "../outside.txt" to
                    "not a ReaderLB package"
            )

        assertNull(
            inspectReaderLbTransfer(
                ByteArrayInputStream(
                    bytes
                )
            )
        )
    }

    @Test
    fun readerLbPackageRejectsUnsafeOrForeignPaths() {
        val bytes =
            zipBytes(
                "readerlb-transfer.json" to
                    manifestText(),
                "book/900000001--test/info.json" to
                    "{}",
                "book/900000001--test/chapters.json" to
                    "[]",
                "../outside.txt" to
                    "unexpected"
            )

        assertIllegalArgument {
            inspectReaderLbTransfer(
                ByteArrayInputStream(
                    bytes
                )
            )
        }
    }

    @Test
    fun oversizedTransferManifestIsRejectedBeforeJsonParsing() {
        val hugeManifest =
            """
            {
              "format":"readerlb-local-title",
              "version":1,
              "title":"",
              "slugUrl":"900000001--test",
              "chapterCount":41,
              "firstChapter":"0",
              "lastChapter":"89"
            }
            """.trimIndent()

        val bytes =
            zipBytes(
                "readerlb-transfer.json" to
                    hugeManifest,
                "book/900000001--test/info.json" to
                    "{}",
                "book/900000001--test/chapters.json" to
                    "[]"
            )

        assertIllegalArgument {
            inspectReaderLbTransfer(
                ByteArrayInputStream(
                    bytes
                )
            )
        }
    }

    @Test
    fun portablePackageDetectionDoesNotDependOnExactSuffix() {
        assertTrue(
            shouldInspectReaderLbTransferFile(
                "title.readerlb.zip"
            )
        )
        assertTrue(
            shouldInspectReaderLbTransferFile(
                "title_1789939295639_readerlb.zip"
            )
        )
        assertTrue(
            shouldInspectReaderLbTransferFile(
                "renamed-package.zip"
            )
        )
        assertFalse(
            shouldInspectReaderLbTransferFile(
                "book.epub"
            )
        )
    }

    @Test
    fun extractionKeepsTitleFilesInsideExpectedDirectory() {
        val bytes = packageBytes()
        val info = requireNotNull(
            inspectReaderLbTransfer(
                ByteArrayInputStream(
                    bytes
                )
            )
        )
        val root =
            Files.createTempDirectory(
                "readerlb_transfer_"
            ).toFile()

        try {
            extractReaderLbTransfer(
                input =
                    ByteArrayInputStream(
                        bytes
                    ),
                info = info,
                rootDir = root
            )

            val titleDir = root.resolve(
                "book/" +
                    info.slugUrl
            )

            assertEquals(
                true,
                titleDir.resolve(
                    "info.json"
                ).isFile
            )
            assertEquals(
                true,
                titleDir.resolve(
                    "chapters.json"
                ).isFile
            )
        } finally {
            root.deleteRecursively()
        }
    }

    private fun packageBytes():
        ByteArray =
        zipBytes(
            "readerlb-transfer.json" to
                manifestText(),
            "book/900000001--test/info.json" to
                "{}",
            "book/900000001--test/chapters.json" to
                "[]"
        )

    private fun manifestText(): String =
        """
        {
          "format":"readerlb-local-title",
          "version":1,
          "title":"Тестовый тайтл",
          "slugUrl":"900000001--test",
          "chapterCount":41,
          "firstChapter":"0",
          "lastChapter":"89"
        }
        """.trimIndent()

    private fun zipBytes(
        vararg entries:
            Pair<String, String>
    ): ByteArray =
        ByteArrayOutputStream()
            .also { output ->
                ZipOutputStream(
                    output
                ).use { zip ->
                    entries.forEach {
                        (name, text) ->
                        zip.putNextEntry(
                            ZipEntry(name)
                        )
                        zip.write(
                            text.toByteArray()
                        )
                        zip.closeEntry()
                    }
                }
            }
            .toByteArray()

    private fun assertIllegalArgument(
        block: () -> Unit
    ) {
        try {
            block()
            fail(
                "Expected IllegalArgumentException"
            )
        } catch (
            expected:
                IllegalArgumentException
        ) {
            // Expected validation failure.
        }
    }
}
